content.content:
variable "name" {
  description = "Name of the service the policy belongs to."
  type        = string
}

variable "retention_days" {
  description = "How many days records are kept."
  type        = number
  default     = 30
}
resource "terraform_data" "policy" {
  input = {
    name           = var.name
    retention_days = var.retention_days
  }
}
terraform {
  required_version = ">= 1.7.0"
}
.PHONY: test integration
test:
	terraform init -backend=false -input=false
	terraform fmt -check -recursive
	terraform test -test-directory=tests/unit

integration:
	terraform init -backend=false -input=false
	terraform test -test-directory=tests/integration
variables {
  name = "billing"
}

run "policy_name_follows_service" {
  command = plan

  assert {
    condition     = output.policy_name == "billing-retention"
    error_message = "policy_name must be the service name followed by -retention."
  }
}
variables {
  name = "billing"
}

run "policy_is_recorded" {
  command = apply

  assert {
    condition     = terraform_data.policy.output.retention_days == 30
    error_message = "The default retention must reach the recorded policy."
  }
}
Terraform v1.17.1
on linux_amd64

